add_leads.beforeRequest:
var vars = inputs.customVariables ? JSON.parse(inputs.customVariables) : [];
var custom = {};
vars.forEach(function (v) { custom[v.key] = v.value; });
var lead = Object.assign({ email: inputs.email, firstName: inputs.firstName, lastName: inputs.lastName || undefined }, custom);
request.body = { campaignId: inputs.campaignId, leads: [lead], newCoreVariables: ['firstName'].concat(vars.map(function (v) { return v.key; })), duplicates: [] };
return request;

add_blocklist.beforeRequest:
var list = function (v) { return v ? JSON.parse(v) : []; };
request.body = { emails: list(inputs.emails), domains: list(inputs.domains), keywords: list(inputs.keywords) };
if (!request.body.emails.length && !request.body.domains.length && !request.body.keywords.length) throw new Error('Please provide at least one email, domain, or keyword to block.');
return request;

update_lead.beforeRequest:
var vars = inputs.customVariables ? JSON.parse(inputs.customVariables) : [];
var custom = {};
vars.forEach(function (v) { custom[v.key] = v.value; });
request.body = { campaignId: Number(inputs.campaignId), leadId: inputs.leadId, email: inputs.email, attributes: Object.assign({ firstName: inputs.firstName || '', lastName: inputs.lastName || '' }, custom) };
return request;
